// 判断是否允许指定距离 ans 可种植坐标 m 树苗数量 dis 指定距离
bool check(vector<int> ans, int m , int dis) {
    int count  = 1;
    int currentPosoition = ans[0];
    for (int i  = 1; i < ans.size(); i++) {
        if (ans[i] - currentPosoition >= dis) {
            count++;
            currentPosoition = ans[i];
        }
    }
    return count >= m;
}

