import java.util.*;
​
public class Main {
    // 判断是否可以以 dis 为最小间隔，放置 m 棵树
    public static boolean check(List<Integer> positions, int m, int dis) {
        int count = 1;  // 第一个点默认放置
        int currentPosition = positions.get(0);
​
        for (int i = 1; i < positions.size(); i++) {
            if (positions.get(i) - currentPosition >= dis) {
                count++;
                currentPosition = positions.get(i);
            }
        }
        return count >= m;
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int n = scanner.nextInt();
        List<Integer> positions = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            positions.add(scanner.nextInt());
        }

        int count = scanner.nextInt();
        scanner.close();
​
        // 排序
        Collections.sort(positions);

        // 二分搜索范围
        int left = 1, right = positions.get(n - 1) - positions.get(0);

        while (left < right) {
            int mid = (left + right + 1) >> 1;  // 向上取整
            if (check(positions, count, mid)) {
                left = mid;  // 继续尝试更大间隔
            } else {
                right = mid - 1;
            }
        }

        System.out.println(left);
    }
}
