package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
// check 判断是否可以以 dis 作为最小间隔放置 m 棵树
func check(positions []int, m int, dis int) bool {
    count := 1  // 默认放置第一棵树
    currentPosition := positions[0]
​
    for i := 1; i < len(positions); i++ {
        if positions[i]-currentPosition >= dis {
            count++
            currentPosition = positions[i]
        }
    }
    return count >= m
}
​
func main() {
    // 使用 bufio 读取输入
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取 n
    scanner.Scan()
    n, _ := strconv.Atoi(strings.TrimSpace(scanner.Text()))
​
    // 读取坐标列表
    scanner.Scan()
    positionStr := strings.Fields(scanner.Text())
    positions := make([]int, n)
    for i := 0; i < n; i++ {
        positions[i], _ = strconv.Atoi(positionStr[i])
    }
​
    // 读取 m
    scanner.Scan()
    m, _ := strconv.Atoi(strings.TrimSpace(scanner.Text()))
​
    // 排序位置数组
    sort.Ints(positions)
​
    // 二分查找最大间距
    left, right := 1, positions[n-1]-positions[0]
    for left < right {
        mid := (left + right + 1) / 2 // 向上取整
        if check(positions, m, mid) {
            left = mid // 继续尝试更大间隔
        } else {
            right = mid - 1
        }
    }
​
    // 输出最终结果
    fmt.Println(left)
}
